-role{font-size:var(--fs-xs)}.flow-label{margin-left:auto;font-size:var(--fs-xs);color:var(--muted)}.success{color:var(--status);font-weight:var(--semibold);margin-bottom:var(--s4);display:flex;align-items:center;gap:var(--s2)}.success-icon{width:var(--s6);height:var(--s6);display:grid;place-items:center;border-radius:var(--r-round);background:var(--tint)}.empty{padding-top:var(--s7);padding-bottom:var(--s6)}.empty-symbol{width:var(--s8);height:var(--s8);color:var(--muted);margin-bottom:var(--s4)}.empty-symbol svg{width:var(--full);height:var(--full);stroke:currentColor;fill:none;stroke-width:var(--focus-offset)}.offline-title{display:flex;align-items:center;justify-content:space-between}.text-btn{background:var(--none);border:var(--s0);color:var(--caution);text-decoration:underline;text-underline-offset:var(--focus-offset);min-height:var(--target);padding:var(--s0) var(--s1);border-radius:var(--r-sm)}.sr-only{position:absolute;width:var(--border);height:var(--border);padding:var(--s0);overflow:hidden;clip-path:inset(var(--full));white-space:nowrap}.compact{margin-top:var(--s3)}.request-link{margin-top:var(--s4);text-align:left;display:block;width:var(--full)}.request-link small{display:block;font-size:var(--fs-xs);font-weight:var(--regular);margin-top:var(--s1)}@media(prefers-reduced-motion:reduce){*{transition:none"'!important;animation:none!important}}
